public class RestaurantDemo {
    public static void main(String[] args) {
        Restaurant restaurant = new Restaurant();

        // Walk through every valid level.
        for (int level = 1; level <= 5; level++) {
            System.out.println(level + " -> " + restaurant.getSpiceLevel(level));
        }

        // Values outside 1-5 fall to the default branch.
        System.out.println("0 -> " + restaurant.getSpiceLevel(0));
        System.out.println("6 -> " + restaurant.getSpiceLevel(6));
        System.out.println("-3 -> " + restaurant.getSpiceLevel(-3));

        // Simple hand-written checks, the same ones a unit test would make.
        check("Mild", restaurant.getSpiceLevel(1));
        check("Medium-Mild", restaurant.getSpiceLevel(2));
        check("Medium", restaurant.getSpiceLevel(3));
        check("Medium-Spicy", restaurant.getSpiceLevel(4));
        check("Spicy", restaurant.getSpiceLevel(5));
        check("Invalid spice level", restaurant.getSpiceLevel(0));
        check("Invalid spice level", restaurant.getSpiceLevel(6));
        check("Invalid spice level", restaurant.getSpiceLevel(-3));

        System.out.println("All checks passed.");
    }

    private static void check(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected \"" + expected + "\" but got \"" + actual + "\"");
        }
    }
}

