public class TeamStatsApp {
    public static void main(String[] args) {
        List<Player> squad = List.of(
                new Player("Amara", "Forward", 18),
                new Player("Bruno", "Forward", 12),
                new Player("Chen", "Forward", 21),
                new Player("Diego", "Midfielder", 9),
                new Player("Elif", "Midfielder", 14),
                new Player("Farid", "Midfielder", 5),
                new Player("Greta", "Defender", 3),
                new Player("Hugo", "Defender", 6),
                new Player("Ines", "Defender", 1),
                new Player("Jonas", "Goalkeeper", 0));

        Map<String, List<Player>> byPosition = squad.stream()
                .collect(Collectors.groupingBy(Player::getPosition));
        System.out.println("Players grouped by position:");
        byPosition.forEach((position, players) -> System.out.println("  " + position + " -> " + players));

        Optional<Player> topScorer = squad.stream()
                .max(Comparator.comparingInt(Player::getGoals));
        System.out.println("\nTop scorer overall: " + topScorer.orElse(null));

        Map<String, Optional<Player>> topByPosition = squad.stream()
                .collect(Collectors.groupingBy(Player::getPosition,
                        Collectors.maxBy(Comparator.comparingInt(Player::getGoals))));
        System.out.println("\nTop scorer in each position:");
        topByPosition.forEach((position, player) ->
                System.out.println("  " + position + " -> " + player.map(Player::getName).orElse("none")));
    }
}
